<template><section class="space-y-6"><RecordTable title="KYC Requests" description="Review provider verification outcomes. Approval requires a verified provider result." endpoint="/api/v1/admin/kyc-requests" search-placeholder="Reference" :statuses="['pending','processing','failed','verified']" :columns="columns" :key="revision" />
<form class="space-y-3 rounded-xl border p-5 text-slate-900 dark:text-slate-100" @submit.prevent="save"><h2 class="font-bold">Record review or retry a failed request</h2><label class="block">Request ID<input v-model="id" required type="number" min="1" class="ml-3 rounded border bg-transparent p-2" /></label><label class="block">Review note<textarea v-model="note" required maxlength="2000" class="block w-full rounded border bg-transparent p-2" /></label><label class="flex items-center gap-2"><input v-model="retry" type="checkbox" />Retry provider verification</label><p v-if="error" role="alert" class="text-red-600">{{ error }}</p><p v-if="message" role="status">{{ message }}</p><button :disabled="busy" class="rounded bg-indigo-600 px-4 py-2 text-white">Save review</button></form></section></template>
<script setup>import{ref}from'vue';import axios from'axios';import RecordTable from'../../components/RecordTable.vue';const columns=[{key:'id',label:'ID'},{key:'reference',label:'Reference'},{key:'customer_name',label:'Customer'},{key:'business_name',label:'Business'},{key:'type',label:'Type'},{key:'masked_identity',label:'Identity'},{key:'status',label:'Status'},{key:'attempts',label:'Attempts'},{key:'review_note',label:'Review'}];const id=ref(''),note=ref(''),retry=ref(false),busy=ref(false),error=ref(''),message=ref(''),revision=ref(0);async function save(){busy.value=true;error.value='';message.value='';try{const{data}=await axios.post('/api/v1/admin/kyc-requests/'+id.value+'/review',{note:note.value,retry:retry.value});message.value=data.message;revision.value++;}catch(e){error.value=Object.values(e.response?.data?.errors||{}).flat().join(' ')||e.response?.data?.message||'Review failed.';}finally{busy.value=false;}}</script>
